-- Corrections: NPCs the journal had recorded at two different places. The
-- verified spot replaces every copy (quest givers, turn-ins, chain steps).
do
    FDJ.NPC_SPOT_CORRECTIONS = {
        -- Wowhead Forever (comments 7.5 / 43.7) and the turn-in spot agree; the
        -- 4.3, 36.1 copies on the Argent Dawn chain steps were wrong.
        ["tirion fordring"] = { mapID = 1423, x = 0.076, y = 0.436, label = "Tirion Fordring — Thondroril River, Eastern Plaguelands", targetName = "Tirion Fordring", detail = "Tirion Fordring: his hut by the Thondroril River, Eastern Plaguelands (7.6, 43.6)" },
        -- Wowhead Forever spawn data: Marris Stead 26.4-26.6, 74.4-74.8.
        -- Wowhead Forever spawn data: Winterspring 54.4-54.6, 51.2 (deep in
        -- Mazthoril); the 57.4, 67.2 turn-in copy was wrong.
        ["haleh"] = { mapID = 1452, x = 0.544, y = 0.512, label = "Haleh — Mazthoril, Winterspring", targetName = "Haleh", detail = "Haleh: deep inside the Mazthoril cave, Winterspring (54.4, 51.2)" },
        -- Wowhead Forever quests 5251/5262/5263: Light's Hope Chapel 81.4, 59.8;
        -- the 73.7, 50.8 copies were wrong.
        ["duke nicholas zverenhoff"] = { mapID = 1423, x = 0.814, y = 0.598, label = "Duke Nicholas Zverenhoff — Light's Hope Chapel, Eastern Plaguelands", targetName = "Duke Nicholas Zverenhoff", detail = "Duke Nicholas Zverenhoff: Light's Hope Chapel, Eastern Plaguelands (81.4, 59.8)" },
        -- Wowhead Forever quest 2279: Hall of Explorers 69.6, 18.6; the 77.2,
        -- 11.8 copy was wrong.
        ["high explorer magellas"] = { mapID = 1455, x = 0.696, y = 0.186, label = "High Explorer Magellas — Hall of Explorers, Ironforge", targetName = "High Explorer Magellas", detail = "High Explorer Magellas: Hall of Explorers, Ironforge (69.6, 18.6)" },
        -- Eastern Plaguelands NPCs the journal had about 8 points west/north of
        -- their Forever spawns (the same offset as the old Zverenhoff spot).
        -- Wowhead Forever quest pages; Light's Hope agrees with the turn-in
        -- spot recorded from Warcraft Tavern's Forever guide.
        ["betina bigglezink"] = { mapID = 1423, x = 0.814, y = 0.596, label = "Betina Bigglezink — Light's Hope Chapel, Eastern Plaguelands", targetName = "Betina Bigglezink", detail = "Betina Bigglezink: Light's Hope Chapel (81.4, 59.6)" },  -- quest 4771
        ["smokey larue"] = { mapID = 1423, x = 0.806, y = 0.580, label = "Smokey LaRue — Light's Hope Chapel, Eastern Plaguelands", targetName = "Smokey LaRue", detail = "Smokey LaRue: Light's Hope Chapel (80.6, 58.0)" },  -- quest 5214
        ["leonid barthalomew the revered"] = { mapID = 1423, x = 0.816, y = 0.578, label = "Leonid Barthalomew the Revered — Light's Hope Chapel, Eastern Plaguelands", targetName = "Leonid Barthalomew the Revered", detail = "Leonid Barthalomew the Revered: Light's Hope Chapel (81.6, 57.8)" },  -- quest 5243
        ["aurora skycaller"] = { mapID = 1423, x = 0.534, y = 0.220, label = "Aurora Skycaller — Northpass Tower, Eastern Plaguelands", targetName = "Aurora Skycaller", detail = "Aurora Skycaller: Northpass Tower (53.4, 22.0)" },  -- quest 5245
        ["caretaker alen"] = { mapID = 1423, x = 0.794, y = 0.638, label = "Caretaker Alen — Light's Hope Chapel, Eastern Plaguelands", targetName = "Caretaker Alen", detail = "Caretaker Alen: Light's Hope Chapel (79.4, 63.8)" },  -- quest 5281
        ["egan"] = { mapID = 1423, x = 0.144, y = 0.336, label = "Egan — Eastern Plaguelands", targetName = "Egan", detail = "Egan: Eastern Plaguelands (14.4, 33.6)" },  -- quest 5281
        ["nathanos blightcaller"] = { mapID = 1423, x = 0.266, y = 0.748, label = "Nathanos Blightcaller — Marris Stead, Eastern Plaguelands", targetName = "Nathanos Blightcaller", detail = "Nathanos Blightcaller: Marris Stead, Eastern Plaguelands (26.6, 74.8)" },
    }
    local fix = FDJ.NPC_SPOT_CORRECTIONS
    local function NameOf(spot)
        local n = spot.targetName or spot.npc
        if not n and type(spot.label) == "string" then n = spot.label:match("^(.-)%s+—") or spot.label end
        return type(n) == "string" and n:lower() or nil
    end
    local function Fixed(spot)
        if type(spot) ~= "table" or not spot.mapID then return spot end
        local name = NameOf(spot)
        local good = name and fix[name]
        if good and (spot.mapID ~= good.mapID or math.abs(spot.x - good.x) > 0.01 or math.abs(spot.y - good.y) > 0.01) then return good end
        return spot
    end
    for id, spot in pairs(FDJ.QUEST_START_MAPS or {}) do FDJ.QUEST_START_MAPS[id] = Fixed(spot) end
    for i, spot in ipairs(FDJ.TURNIN_SPOTS or {}) do FDJ.TURNIN_SPOTS[i] = Fixed(spot) end
    for _, details in pairs(FDJ.QUEST_PREREQ_DETAILS or {}) do
        if type(details) == "table" then
            details.map, details.turninMap = Fixed(details.map), Fixed(details.turninMap)
            -- Chain steps that name a corrected NPC but had no spot get it too.
            for field, text in pairs({ map = details.pickup, turninMap = details.turnin }) do
                if not details[field] and type(text) == "string" and not (field == "map" and details.startItem) then
                    local npc = text:match("^([^,(]+)")
                    npc = npc and npc:gsub("%s+$", ""):lower()
                    if npc and fix[npc] then details[field] = fix[npc] end
                end
            end
        end
    end
    for _, dungeon in pairs(FDJ.DB or {}) do
        for _, quest in ipairs((type(dungeon) == "table" and dungeon.quests) or {}) do
            quest.turninMap, quest.startMap = Fixed(quest.turninMap), Fixed(quest.startMap)
        end
    end
end

-- Fill the gaps, never overwrite: hand-placed spots (checked in game) win.
do
    local SPOTS = FDJ.WOWHEAD_QUEST_SPOTS
    -- Forever's Stormwind map does not line up with Wowhead's (classic)
    -- Stormwind coordinates: every Stormwind NPC checked in game sits
    -- elsewhere. Those spots are left out.
    local SKIP_MAPS = { [1453] = true }
    local CITY = { [1458] = true, [1453] = true, [1455] = true, [1454] = true, [1456] = true, [1457] = true }
    local function Usable(spot)
        if type(spot) ~= "table" or not spot.mapID or SKIP_MAPS[spot.mapID] then return nil end
        -- Mobs with many spawns filed under a city (lake mobs "in Undercity")
        -- are on the wrong map.
        if CITY[spot.mapID] and (spot.spawns or 1) > 2 then return nil end
        return spot
    end
    local function Coord(spot) return string.format("%.1f, %.1f", spot.x * 100, spot.y * 100) end
    local function Same(a, b)
        return a and b and a.mapID == b.mapID and math.abs(a.x - b.x) < 0.02 and math.abs(a.y - b.y) < 0.02
    end
    -- "Where to go" lines for the quest page: each objective out in the
    -- world with its coordinates, and the dungeons the rest is done in.
    local function WhereText(w, insideAlone)
        local lines = {}
        for _, o in ipairs(w.objectives or {}) do
            if Usable(o) and #lines < 4 then
                local line = o.item and (o.item .. " — from " .. o.label) or o.label
                lines[#lines + 1] = line .. " (" .. Coord(o) .. ")"
            end
        end
        if #lines == 0 and not insideAlone then return nil end
        for _, name in ipairs(w.inside or {}) do
            if #lines < 5 then lines[#lines + 1] = "Inside " .. name end
        end
        if #lines == 0 then return nil end
        return "Where to go:\n" .. table.concat(lines, "\n")
    end
    local function FirstObjective(w)
        -- An item that mostly drops inside a dungeon gets no button for its
        -- odd outdoor source (a chest in Duskwood for a Blackrock Depths gem).
        if w.inside and #w.inside > 0 then
            local items = false
            for _, o in ipairs(w.objectives or {}) do if o.item then items = true end end
            if items then return nil end
        end
        for _, o in ipairs(w.objectives or {}) do
            if Usable(o) and not Same(o, w.finish) and not Same(o, w.start) then return o end
        end
    end

    FDJ.QUEST_START_MAPS = FDJ.QUEST_START_MAPS or {}
    local filled = { start = 0, turnin = 0, objective = 0, text = 0 }

    for _, dungeon in pairs(FDJ.DB or {}) do
        for _, quest in ipairs((type(dungeon) == "table" and dungeon.quests) or {}) do
            local w = quest.id and SPOTS[quest.id]
            if w then
                local start = Usable(w.start)
                if start and not FDJ.QUEST_START_MAPS[quest.id] and not quest.startMap and not quest.startItem then
                    FDJ.QUEST_START_MAPS[quest.id] = start
                    filled.start = filled.start + 1
                end
                local finish = Usable(w.finish)
                if finish and not quest.turninMap and not (FDJ.FindTurninLocation and FDJ.FindTurninLocation(quest)) then
                    quest.turninMap = finish
                    filled.turnin = filled.turnin + 1
                end
                local objective = FirstObjective(w)
                if objective and not quest.objectiveMap then
                    quest.objectiveMap = objective
                    quest.objectiveWhere = objective.detail
                    filled.objective = filled.objective + 1
                end
                local where = WhereText(w)
                if where and (not quest.note or quest.note == "") then
                    quest.note = where
                    filled.text = filled.text + 1
                end
            end
        end
    end

    for id, details in pairs(FDJ.QUEST_PREREQ_DETAILS or {}) do
        local w = type(details) == "table" and SPOTS[id]
        if w then
            local start = Usable(w.start)
            if start and not details.map and not details.startItem then
                details.map = start
                filled.start = filled.start + 1
            end
            local finish = Usable(w.finish)
            if finish and not details.turninMap then
                details.turninMap = finish
                filled.turnin = filled.turnin + 1
            end
            local objective = FirstObjective(w)
            if objective and not details.objectiveMap then
                details.objectiveMap = objective
                filled.objective = filled.objective + 1
            end
            local where = WhereText(w, true)
            if where and (not details.description or details.description == "") then
                details.description = where
                filled.text = filled.text + 1
            end
        end
    end
    FDJ.WOWHEAD_SPOTS_FILLED = filled
end
